#pragma warning disable 8981

using System.Collections.Generic;
using System.IO;

namespace Ros.Config
{
    public partial class ConfigManager
    {
        public Dictionary<int, revive_time> revive_timeData;
        public revive_time Getrevive_timeConfig(int key)
        {
            return ConfigBinary.Require(revive_timeData, key, "revive_time");
        }
        private void Loadrevive_timeConfig()
        {
            using (BinaryReader r = ConfigBinary.Open("revive_time"))
            {
                int count = r.ReadInt32();
                revive_timeData = new Dictionary<int, revive_time>(count);
                for (int i = 0; i < count; i++)
                {
                    revive_time row;
                    row.key = r.ReadInt32();
                    row.reviveIndex = r.ReadInt32();
                    row.attackReviveSeconds = r.ReadInt32();
                    row.defenseReviveSeconds = r.ReadInt32();
                    revive_timeData.Add(row.key, row);
                }
            }
        }
    }
    public struct revive_time
    {
        public int key;  // 主键
        public int reviveIndex;  // 第x次复活：复活的累计次数
        public int attackReviveSeconds;  // 进攻方复活时间：秒
        public int defenseReviveSeconds;  // 防守方复活时间：秒
    }
}
